import{_ as s,C as d,c as a,o as r,ah as n,G as i}from"./chunks/framework.BjIn8lrq.js";const m=JSON.parse('{"title":"29. Architekturüberblick","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/29-architekturueberblick.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/29-architekturueberblick.md"}'),o={name:"manual/teil-c-entwicklungs-systemdokumentation/29-architekturueberblick.md"};function l(c,e,p,u,g,b){const t=d("MermaidDiagram");return r(),a("div",null,[e[0]||(e[0]=n('<h1 id="_29-architekturuberblick" tabindex="-1">29. Architekturüberblick <a class="header-anchor" href="#_29-architekturuberblick" aria-label="Permalink to &quot;29. Architekturüberblick&quot;">​</a></h1><p>Dieses Kapitel beschreibt, aus welchen Teilen Qonnectra besteht, welchen Weg eine Anfrage durch sie nimmt und wo im Repository was liegt. Es ist der Einstieg in Teil C; die folgenden Kapitel vertiefen je einen Teil. Welche Dienste eine Installation betreibt und wofür, steht bereits in Kapitel <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html">Betrieb der Instanz</a> – dieses Kapitel setzt die Tabelle dort voraus und wiederholt sie nicht.</p><p>Die Angaben beziehen sich auf die jeweils aktuelle Veröffentlichung von Qonnectra.</p><h2 id="_29-1-komponenten-und-weg-einer-anfrage" tabindex="-1">29.1 Komponenten und Weg einer Anfrage <a class="header-anchor" href="#_29-1-komponenten-und-weg-einer-anfrage" aria-label="Permalink to &quot;29.1 Komponenten und Weg einer Anfrage&quot;">​</a></h2><p>Qonnectra besteht aus drei eigenen Teilen und einer Reihe fertiger Dienste:</p><ul><li><strong>Backend</strong> – eine Django-Anwendung mit Django REST Framework. Sie stellt die Schnittstelle unter <code>/api/v1/</code> und den Administrationsbereich bereit, enthält die Fachlogik (Routing, Faserweg, Störungsanalyse, Wertermittlung) und erzeugt die Vektorkacheln der Netzobjekte.</li><li><strong>Frontend</strong> – eine SvelteKit-Anwendung, die die Weboberfläche ausliefert. Sie läuft als eigener Node-Prozess, rendert Seiten auf dem Server vor und spricht dafür selbst mit dem Backend.</li><li><strong>Datenbank</strong> – PostgreSQL mit PostGIS. Ein Teil der Fachlogik liegt als Trigger in der Datenbank selbst, siehe Kapitel <a href="./31-datenmodell-des-backends.html">Datenmodell des Backends</a>.</li></ul><p>Dazu kommen die fertigen Dienste aus der Tabelle in Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-1-systemuberblick-dienste-und-ihre-aufgaben">Systemüberblick</a>.</p><p>Eine Installation hat sechs Adressen. Caddy nimmt alle Anfragen an, beendet TLS und verteilt sie nach Adresse:</p><table tabindex="0"><thead><tr><th>Adresse</th><th>Ziel</th><th>Prüfung vor der Weiterleitung</th></tr></thead><tbody><tr><td><code>APP_DOMAIN</code></td><td><code>frontend:3000</code></td><td>keine, das Frontend prüft selbst</td></tr><tr><td><code>API_DOMAIN</code></td><td><code>nginx:80</code> → <code>backend</code></td><td>keine; <code>/admin/*</code> beantwortet Caddy hier mit 404</td></tr><tr><td><code>ADMIN_DOMAIN</code></td><td><code>nginx:80</code> → <code>backend</code></td><td>keine, der Administrationsbereich hat eine eigene Anmeldung</td></tr><tr><td><code>FILES_DOMAIN</code></td><td>WebDAV-Modul von Caddy auf dem Medienordner</td><td><code>forward_auth</code> gegen <code>/api/v1/auth/webdav-auth/</code></td></tr><tr><td><code>QGIS_DOMAIN</code></td><td><code>qgis-server:80</code></td><td><code>forward_auth</code> gegen <code>/api/v1/auth/qgis-auth/</code></td></tr><tr><td><code>TILE_SERVER_DOMAIN</code></td><td><code>tileserver:8080</code></td><td>keine</td></tr></tbody></table><p>Backend und Administrationsbereich sind derselbe Prozess unter zwei Adressen. Die Trennung entsteht nur dadurch, dass Caddy <code>/admin/*</code> auf der Adresse der Schnittstelle sperrt.</p>',10)),i(t,{code:"flowchart%20TB%0A%20%20browser(%5BBrowser%5D)%0A%20%20qgis(%5BQGIS%20Desktop%5D)%0A%0A%20%20caddy%5BCaddy%5D%0A%20%20frontend%5Bfrontend%20%C2%B7%20SvelteKit%5D%0A%20%20nginx%5Bnginx%5D%0A%20%20tileserver%5Btileserver%5D%0A%20%20backend%5Bbackend%20%C2%B7%20Django%5D%0A%20%20backendwms%5Bbackend-wms%20%C2%B7%20Django%5D%0A%20%20qgisserver%5Bqgis-server%5D%0A%20%20media%5B%2FMedienordner%2F%5D%0A%20%20wireguard%5Bwireguard%5D%0A%20%20db%5B(db%20%C2%B7%20PostgreSQL%20%2B%20PostGIS)%5D%0A%0A%20%20browser%20--%20%22app.%20%C2%B7%20api.%20%C2%B7%20admin.%20%C2%B7%20tiles.%22%20--%3E%20caddy%0A%20%20qgis%20--%20%22qgis.%20%C2%B7%20files.%22%20--%3E%20caddy%0A%20%20qgis%20--%20%22VPN%22%20--%3E%20wireguard%0A%0A%20%20caddy%20--%20%22app.%22%20--%3E%20frontend%0A%20%20caddy%20--%20%22api.%20%C2%B7%20admin.%22%20--%3E%20nginx%0A%20%20caddy%20--%20%22tiles.%22%20--%3E%20tileserver%0A%20%20caddy%20--%20%22qgis.%22%20--%3E%20qgisserver%0A%20%20caddy%20--%20%22files.%22%20--%3E%20media%0A%20%20caddy%20-.%20%22forward_auth%22%20.-%3E%20nginx%0A%0A%20%20frontend%20--%20%22API_URL%22%20--%3E%20backend%0A%20%20nginx%20--%3E%20backend%0A%20%20nginx%20--%20%22wms-proxy%22%20--%3E%20backendwms%0A%20%20backendwms%20--%3E%20qgisserver%0A%0A%20%20backend%20--%3E%20db%0A%20%20backendwms%20--%3E%20db%0A%20%20qgisserver%20--%3E%20db%0A%20%20wireguard%20--%3E%20db%0A"}),e[1]||(e[1]=n(`<p>Für die Weboberfläche gibt es zwei Wege zum Backend, und welcher genommen wird, hängt davon ab, wo der Code läuft:</p><ul><li><strong>Auf dem Server.</strong> Lade-Funktionen, Formularaktionen und Remote Functions des Frontends laufen im Container <code>frontend</code> und erreichen das Backend über <code>API_URL</code> direkt im Docker-Netz (<code>http://backend:8000/api/v1/</code>), an Caddy und nginx vorbei. Die Anmelde-Cookies des Browsers reicht das Frontend dabei weiter.</li><li><strong>Im Browser.</strong> Alles, was die Seite nach dem Laden selbst holt – Vektorkacheln der Karte, WMS-Bilder, Suchtreffer, Speichervorgänge –, geht über <code>PUBLIC_API_URL</code> an die Adresse der Schnittstelle, also durch Caddy und nginx. Die Cookies gelten für alle Adressen der Installation, weil sie auf die gemeinsame Domain gesetzt werden (<code>COOKIE_DOMAIN</code>).</li></ul><p>Wie die Anmeldung über beide Wege funktioniert und wann das Frontend die Tokens erneuert, beschreiben die Kapitel <a href="./32-rest-api.html">REST-API</a> und <a href="./33-frontend.html">Frontend</a>.</p><p>nginx ist mehr als eine Weiterleitung. Es liefert die statischen Dateien des Administrationsbereichs aus, gibt Anhänge erst aus, nachdem das Backend den Zugriff geprüft und per <code>X-Accel-Redirect</code> freigegeben hat, und hält zwei Zwischenspeicher: Vektorkacheln der Netzobjekte für 30 Sekunden, WMS-Bilder für 30 Tage. Die WMS-Anfragen gibt es an <code>backend-wms</code> weiter, dasselbe Image mit eigenem Prozesspool.</p><p>Die Karte der Weboberfläche setzt sich aus drei Quellen zusammen, die nichts miteinander zu tun haben:</p><ul><li><strong>Hintergrundkarte</strong> – Vektorkacheln von TileServer GL unter <code>TILE_SERVER_DOMAIN</code>, aus einer <code>.mbtiles</code>-Datei. Ohne sie fällt die Karte auf OpenStreetMap-Rasterkacheln zurück.</li><li><strong>Netzobjekte</strong> – Trassen, Netzknoten, Adressen und Gebiete als Vektorkacheln, die das Backend pro Anfrage in PostGIS erzeugt (<code>/api/v1/ol_*_tiles/</code>).</li><li><strong>WMS-Ebenen</strong> – Bilder des eigenen QGIS Servers oder externer Dienste, abgerufen über den WMS-Proxy des Backends.</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Holt das Backend die Fähigkeiten eines WMS von der eigenen <code>QGIS_DOMAIN</code>, schreibt es die Adresse auf <code>http://qgis-server</code> im Docker-Netz um. Über die öffentliche Adresse liefe die Anfrage durch die Anmeldeprüfung von Caddy zurück an das Backend selbst und bliebe hängen.</p></div><h2 id="_29-2-technologiestack" tabindex="-1">29.2 Technologiestack <a class="header-anchor" href="#_29-2-technologiestack" aria-label="Permalink to &quot;29.2 Technologiestack&quot;">​</a></h2><p>Die Versionen sind die der Sperrdateien (<code>backend/uv.lock</code>, <code>frontend/package-lock.json</code>) und der Container-Images zum Stand des Handbuchs.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Image des Backends hält sich nicht an <code>backend/uv.lock</code>. Sein Dockerfile installiert mit <code>pip install .</code> die jeweils neuesten Versionen innerhalb der Grenzen aus <code>backend/pyproject.toml</code>; was im Container läuft, hängt deshalb vom Tag des Builds ab. Ein im Oktober 2026 gebautes Image enthielt etwa Django 5.2.17, Django REST Framework 3.18.1 und gunicorn 26.2.0 statt der Versionen der Tabelle. Die Tabelle gilt für die Entwicklungsumgebung, die <code>uv sync</code> aus der Sperrdatei einrichtet. Das Frontend baut dagegen mit <code>npm ci</code> genau nach <code>package-lock.json</code>.</p></div><p><strong>Backend</strong></p><table tabindex="0"><thead><tr><th>Baustein</th><th>Version</th><th>Aufgabe</th></tr></thead><tbody><tr><td>Python</td><td>3.12</td><td>Laufzeit, Image <code>python:3.12-slim</code></td></tr><tr><td>Django</td><td>5.2.10</td><td>Webframework, Administrationsbereich, ORM mit GeoDjango</td></tr><tr><td>Django REST Framework</td><td>3.15.2</td><td>Schnittstelle</td></tr><tr><td>djangorestframework-gis</td><td>1.1</td><td>Geometrien in Serialisierern</td></tr><tr><td>dj-rest-auth, djangorestframework-simplejwt</td><td>7.0.1, 5.5.0</td><td>Anmeldung mit JWT in Cookies</td></tr><tr><td>drf-spectacular</td><td>0.30.0</td><td>OpenAPI-Schema</td></tr><tr><td>django-simple-history</td><td>3.11.0</td><td>Änderungsverlauf</td></tr><tr><td>networkx</td><td>3.5</td><td>Graphen für Routing und Kabellängen</td></tr><tr><td>GeoPandas</td><td>1.1.0</td><td>GeoPackage-Erzeugung</td></tr><tr><td>psycopg</td><td>3.2.6</td><td>Datenbanktreiber</td></tr><tr><td>gunicorn</td><td>23.0.0</td><td>Anwendungsserver</td></tr></tbody></table><p><strong>Frontend</strong></p><table tabindex="0"><thead><tr><th>Baustein</th><th>Version</th><th>Aufgabe</th></tr></thead><tbody><tr><td>Node.js</td><td>22</td><td>Laufzeit, Image <code>node:22-alpine</code>, <code>@sveltejs/adapter-node</code></td></tr><tr><td>Svelte, SvelteKit</td><td>5.56.10, 2.66.0</td><td>Oberfläche und Server-Rendering</td></tr><tr><td>Vite</td><td>8.0.16</td><td>Build</td></tr><tr><td>TypeScript</td><td>5.9.3</td><td>Typprüfung</td></tr><tr><td>OpenLayers, ol-mapbox-style</td><td>10.7.0, 13.2.0</td><td>Karte und Hintergrundkarte</td></tr><tr><td>Svelte Flow (<code>@xyflow/svelte</code>)</td><td>1.6.5</td><td>Netzschema, Rohrverzweigung und Grabenprofil</td></tr><tr><td>Chart.js</td><td>4.5.1</td><td>Diagramme des Dashboards</td></tr><tr><td>Skeleton, Tailwind CSS</td><td>5.0.1, 4.3.1</td><td>Komponenten und Gestaltung</td></tr><tr><td>Paraglide</td><td>2.12.0</td><td>Übersetzungen</td></tr></tbody></table><p><strong>Dienste</strong></p><table tabindex="0"><thead><tr><th>Dienst</th><th>Image</th></tr></thead><tbody><tr><td>Datenbank</td><td>eigenes Image auf Basis von <code>postgis/postgis:17-3.5</code> (PostgreSQL 17, PostGIS 3.5, pgRouting)</td></tr><tr><td>QGIS Server</td><td><code>qgis/qgis-server:3.44.7-noble</code></td></tr><tr><td>Hintergrundkarte</td><td><code>maptiler/tileserver-gl:v5.6.0</code></td></tr><tr><td>Reverse Proxy</td><td>eigenes Image auf Basis von <code>caddy:2</code> mit dem Modul <code>caddy-webdav</code></td></tr><tr><td>Vorstufe des Backends</td><td><code>nginx:stable-alpine</code></td></tr><tr><td>VPN</td><td><code>lscr.io/linuxserver/wireguard:latest</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>pgRouting ist im Datenbank-Image installiert, wird aber nicht genutzt. Routing und Kabellängen berechnet das Backend in Python mit networkx.</p></div><h2 id="_29-3-verzeichnisstruktur-des-repositorys" tabindex="-1">29.3 Verzeichnisstruktur des Repositorys <a class="header-anchor" href="#_29-3-verzeichnisstruktur-des-repositorys" aria-label="Permalink to &quot;29.3 Verzeichnisstruktur des Repositorys&quot;">​</a></h2><p>Das Repository <a href="https://github.com/Geodock-GmbH/Qonnectra" target="_blank" rel="noreferrer">Geodock-GmbH/Qonnectra</a> enthält Backend, Frontend und Bereitstellung in einem:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>backend/</span></span>
<span class="line"><span>  apps/api/          die einzige Django-App: Modelle, Schnittstelle, Fachlogik</span></span>
<span class="line"><span>    fixtures/        Stammdaten für load_initial_data</span></span>
<span class="line"><span>    management/      Verwaltungsbefehle</span></span>
<span class="line"><span>    migrations/      Migrationen, viele davon mit SQL für Trigger</span></span>
<span class="line"><span>    tests/           pytest-Tests</span></span>
<span class="line"><span>  core/              Projektpaket: settings.py, urls.py, wsgi.py, asgi.py</span></span>
<span class="line"><span>  locale/            Übersetzungen des Backends (gettext)</span></span>
<span class="line"><span>  templates/         Vorlagen des Administrationsbereichs</span></span>
<span class="line"><span>  schema.yml         OpenAPI-Schema, Quelle der Frontend-Typen</span></span>
<span class="line"><span>frontend/</span></span>
<span class="line"><span>  src/routes/        eine Route je Menüpunkt, dazu login, logout, admin/logs</span></span>
<span class="line"><span>                     und api (Server-Endpunkte)</span></span>
<span class="line"><span>  src/lib/           classes, components, config, context, map, remote,</span></span>
<span class="line"><span>                     server, stores, test-utils, types, utils</span></span>
<span class="line"><span>  messages/          Texte der Oberfläche, de.json und en.json</span></span>
<span class="line"><span>  project.inlang/    Einstellungen von Paraglide</span></span>
<span class="line"><span>  tests/e2e/         Playwright-Tests</span></span>
<span class="line"><span>deployment/</span></span>
<span class="line"><span>  docker-compose.yml       Produktion</span></span>
<span class="line"><span>  docker-compose.dev.yml   Entwicklung mit lokalem HTTPS (startet nicht, siehe 30.4)</span></span>
<span class="line"><span>  Caddyfile, Caddyfile.production</span></span>
<span class="line"><span>  nginx/, postgres/, qgis/, tiles/, caddy/, wireguard/, backup/</span></span>
<span class="line"><span>.github/workflows/   CI des Frontends, Playwright, release-please</span></span>
<span class="line"><span>pytest.ini           Testkonfiguration des Backends</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><p>Die Fachlogik des Backends ist auf wenige große Module verteilt: <code>views.py</code> enthält die Endpunkte, <code>services.py</code> Faserweg, Signalanalyse, Störungsanalyse und Wertermittlung sowie Excel-Import, GeoPackage-Erzeugung und Dateiablage, <code>routing.py</code> das Routing über networkx, <code>search.py</code> die Ähnlichkeitssuche, <code>wms_service.py</code> den WMS-Proxy.</p><p>Im Frontend liegen Komponenten, die nur eine Ansicht braucht, neben ihrer Route in <code>src/routes/</code>; was mehrere Ansichten teilen, liegt in <code>src/lib/</code>.</p><h2 id="_29-4-lizenz-herkunft-und-beteiligte" tabindex="-1">29.4 Lizenz, Herkunft und Beteiligte <a class="header-anchor" href="#_29-4-lizenz-herkunft-und-beteiligte" aria-label="Permalink to &quot;29.4 Lizenz, Herkunft und Beteiligte&quot;">​</a></h2><p>Qonnectra steht unter der <strong>GNU Affero General Public License, Version 3</strong> (<code>AGPL-3.0-only</code>). Die AGPL verlangt über die GPL hinaus, dass jede Stelle, die eine veränderte Fassung als Netzdienst betreibt, den Nutzenden dieses Dienstes deren Quelltext zugänglich macht.</p><p>Entwickelt wird Qonnectra von der Geodock GmbH gemeinsam mit der plan[neo] GmbH; das Repository gehört der Geodock GmbH. Die Ansprechpersonen für die Pflege stehen in <code>publiccode.yml</code> im Wurzelverzeichnis, einer maschinenlesbaren Beschreibung nach dem Standard <a href="https://yml.publiccode.tools/" target="_blank" rel="noreferrer">publiccode.yml</a> für Software der öffentlichen Hand. Wie Beiträge, Versionen und Veröffentlichungen ablaufen, beschreibt Kapitel <a href="./36-erweitern-und-mitwirken.html">Erweitern und mitwirken</a>.</p>`,25))])}const k=s(o,[["render",l]]);export{m as __pageData,k as default};
